import { createWorkflowChain } from '@voltagent/core';
import { z } from 'zod';

export const parallelWorkflow = createWorkflowChain({
  id: "parallel-workflow",
  input: z.string(),
  result: z.object({
    analysis1: z.string(),
    analysis2: z.string()
  })
})
.andAll({
  id: "parallel-analysis",
  steps: [
    {
      id: "analysis1",
      execute: async ({ data }) => {
        return { analysis1: `Result 1 for ${data}` };
      }
    },
    {
      id: "analysis2",
      execute: async ({ data }) => {
        return { analysis2: `Result 2 for ${data}` };
      }
    }
  ]
});

