import { createWorkflowChain, andThen } from '@voltagent/core';
import { z } from 'zod';

export const parallelWorkflow = createWorkflowChain({
  id: "parallel-workflow",
  name: "Parallel Workflow",
  purpose: "Demonstrate parallel processing",
  input: z.string(),
  result: z.object({
    analysis1: z.string(),
    analysis2: z.string()
  })
})
.andAll({
  id: "parallel-analysis",
  steps: [
    andThen({
      id: "analysis1",
      name: "Analysis 1",
      purpose: "First analysis step",
      execute: async ({ data }) => {
        return { analysis1: `Result 1 for ${data}` };
      }
    }),
    andThen({
      id: "analysis2",
      name: "Analysis 2",
      purpose: "Second analysis step",
      execute: async ({ data }) => {
        return { analysis2: `Result 2 for ${data}` };
      }
    })
  ]
});

